            aCross = RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 32182U)) & S_BLOCK1], 35U) ^ RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 29006U)) & S_BLOCK1], 43U);
