            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xF9A9DA315B5CB13BULL) ^ aPhaseDOrbiterUpdateSaltB[((aIndex + 12U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x2A2927903027CBBFULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x10E51C55324A335EULL;
