            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0xA299DA55F972AF3CULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterJ) ^ 0x8672FDE3BCB59FD7ULL) ^ aNonceWordC;
