            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0x8DF5D8AD07DB013CULL) + aPhaseDOrbiterUpdateSaltC[((aIndex + 3U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0xB184474D977C1FB4ULL) ^ aPhaseDOrbiterUpdateSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x541C3140AB7F01E5ULL), 51U);
