            aScatter = (RotL64(aCarry, 40U) + RotL64(aIngress, 53U)) ^ (RotL64(aCross, 19U) + RotL64(aPrevious, 3U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterA = (aWandererH + RotL64(aPrevious, 41U)) + 0x62462412ECC89DB9ULL;
            aOrbiterD = (((aWandererG + RotL64(aCross, 53U)) + RotL64(aCarry, 3U)) + 0x4BA8CDB97354E1C5ULL) + aPhaseDOrbiterAssignSaltB[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterG = (aWandererF + RotL64(aIngress, 34U)) + 0xEC3DEFD13C7F50CEULL;
            aOrbiterI = (aWandererJ + RotL64(aScatter, 21U)) + 0x841791874687B199ULL;
            aOrbiterC = ((aWandererE + RotL64(aIngress, 5U)) + RotL64(aCarry, 47U)) + 0xAE62D8482C32F48AULL;
            aOrbiterB = ((aWandererA + RotL64(aPrevious, 27U)) + RotL64(aCarry, 29U)) + 0x9B72DDB2533083E1ULL;
            aOrbiterH = ((aWandererK + RotL64(aScatter, 47U)) + 0xEF6B41C28506383CULL) + aPhaseDOrbiterAssignSaltA[((aIndex + 4U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x73C994791383F015ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x1EC36A9BE1392FCEULL;
            aOrbiterG = RotL64((aOrbiterG * 0x982945D423C1382DULL), 23U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x3EA6A3E1A6810C67ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x05BBAA1C8B5FB9B2ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x9967274BAFBD9027ULL), 43U);
