            aOrbiterB = (aOrbiterB + aOrbiterH) + 0xCA95D3A121B2FACFULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x2A1758CC260E5708ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xDE175F13EA1513F3ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x904C31D6342CD547ULL;
