            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x62F33DBD8C107895ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x0B1169E986AD6557ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x07D0C5F65C4F71BDULL), 57U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x8440CDF6C6859784ULL) + aPhaseDOrbiterUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x2043F47B5E20994DULL) ^ aPhaseDOrbiterUpdateSaltA[(((31U - aIndex) + 29U)) & S_SALT1];
