            aOrbiterG = (((aWandererI + RotL64(aScatter, 19U)) + RotL64(aCarry, 53U)) + 0x4D2792D432721D53ULL) + aPhaseAOrbiterAssignSaltA[(((31U - aIndex) + 20U)) & S_SALT1];
