            aCross = (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 7133U)) & S_BLOCK1], 46U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 6021U)) & S_BLOCK1], 35U));
