            aOrbiterH = (((aWandererK + RotL64(aPrevious, 53U)) + RotL64(aCarry, 51U)) + 0x9B5AD46A566825A0ULL) + aPhaseBOrbiterAssignSaltE[((aIndex + 19U)) & S_SALT1];
