            aOrbiterA = RotL64((aOrbiterA * 0xB91FA5D08F7A674FULL), 35U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x450CD8BDDD8CEE77ULL) + aPhaseDOrbiterUpdateSaltE[(((31U - aIndex) + 4U)) & S_SALT1];
