            aOrbiterF = ((aWandererB + RotL64(aPrevious, 5U)) + 0xE5A8E2CE7F1D7DCFULL) + aPhaseAOrbiterAssignSaltB[((aIndex + 17U)) & S_SALT1];
            aOrbiterI = ((aWandererI + RotL64(aScatter, 23U)) + RotL64(aCarry, 27U)) + 0x477954A3A5451976ULL;
            aOrbiterJ = ((aWandererG + RotL64(aIngress, 39U)) + 0xF643F6481E9FD62DULL) + aPhaseAOrbiterAssignSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
