            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0x1F8FC976C2E0EB42ULL) ^ aPhaseAOrbiterUpdateSaltC[(((31U - aIndex) + 25U)) & S_SALT1];
