            //
            aIngress = (RotL64(aHeartLaneA[((aIndex + 1098U)) & S_BLOCK1], 19U) ^ RotL64(aHeartLaneB[((aIndex + 3030U)) & S_BLOCK1], 47U));
            aIngress ^= (RotL64(aPoisonLaneC[((aIndex + 1150U)) & S_BLOCK1], 6U) ^ RotL64(aEarthLaneD[((aIndex + 570U)) & S_BLOCK1], 39U));
