            aCross = (RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 7004U)) & S_BLOCK1], 57U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 4226U)) & S_BLOCK1], 22U));
