            //
            aScatter = (RotL64(aCross, 54U) + RotL64(aIngress, 41U)) ^ (RotL64(aCarry, 5U) + RotL64(aPrevious, 21U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterE = (((aWandererC + RotL64(aCross, 13U)) + RotL64(aCarry, 37U)) + 0xBDD9883ECBE79635ULL) + aPhaseBOrbiterAssignSaltD[((aIndex + 14U)) & S_SALT1];
            aOrbiterH = ((aWandererG + RotL64(aPrevious, 27U)) + 0x714B67A15CEB283DULL) + aPhaseBOrbiterAssignSaltA[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterD = ((aWandererF + RotL64(aIngress, 57U)) + RotL64(aCarry, 13U)) + 0x78CA352E0B1A0A0EULL;
            aOrbiterF = ((aWandererJ + RotL64(aScatter, 3U)) + RotL64(aCarry, 57U)) + 0x5299F44CC6C11626ULL;
            aOrbiterJ = (aWandererI + RotL64(aCross, 39U)) + 0xD92BB3EEBDC3CA2FULL;
            aOrbiterB = (aWandererB + RotL64(aIngress, 46U)) + 0xD27E6972BD34178CULL;
            aOrbiterI = (aWandererH + RotL64(aScatter, 19U)) + 0x215AB43146E8FB6AULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x2E21180A206AB989ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x45EA33017970C6DBULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7DB45B4FC08EE207ULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xEDF5563475C93D79ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0xDA061DBABF57035AULL) ^ aPhaseBOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x9DC7C92A7230E657ULL), 5U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0x3BBBA3935E1B2C05ULL) + aPhaseBOrbiterUpdateSaltB[((aIndex + 28U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x31CA032C7204EDC8ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE0B86F40C2608399ULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0xC7DEC635A74C2462ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0x2CD0614DBE73D4A7ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x70EF6CD0D819A1E9ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x0C9779C7AE3D6E94ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0xABBCE0846C5610CDULL) ^ aPhaseBOrbiterUpdateSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xCDC7E8CBF48BDA9BULL), 39U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xA29D66D0568AF302ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0xD12D608CB465332EULL;
